/* Kinoza · phases, postures et bibliothèque d'exercices */

const PHASES = ["Protection","Mobilité","Renforcement","Retour à l'activité"]; // niveau minimal des exercices
const PHASE_GROUPS = [
  ["Réadaptation",["Évaluation initiale","Protection","Mobilité","Renforcement","Retour à l'activité"]],
  ["Entraînement",["Préparation générale","Hypertrophie","Force","Puissance","Endurance","Affûtage (avant compétition)","Maintien"]],
  ["Autre",["Prévention","Transition (repos actif)"]]
];
const PHASE_ALL = PHASE_GROUPS.flatMap(g=>g[1]);
function phaseField(id,value,label,off){
  const custom = value && !PHASE_ALL.includes(value);
  return `<div class="field"><label for="${id}">${label||"Phase"}</label>
    <select class="inp phase-sel" id="${id}" data-phase-field ${off?"disabled":""}>
      ${value?"":`<option value="" selected>Choisir une phase</option>`}
      ${PHASE_GROUPS.map(([g,l])=>`<optgroup label="${g}">${l.map(x=>`<option ${x===value?"selected":""}>${esc(x)}</option>`).join("")}</optgroup>`).join("")}
      <option value="__custom" ${custom?"selected":""}>Personnalisée…</option>
    </select>
    <input class="inp" id="${id}-custom" data-phase-custom="${id}" placeholder="Nom de la phase, ex. Bloc 2 : force maximale" value="${custom?esc(value):""}" ${custom?"":"hidden"} ${off?"disabled":""} aria-label="Phase personnalisée"></div>`;
}
const phaseVal = id=>{const v=$("#"+id).value; return v==="__custom"?$("#"+id+"-custom").value.trim():v};
const phaseTxt = p=>p.phase||"Phase à préciser";
const DAYS_LONG = ["Lun","Mar","Mer","Jeu","Ven","Sam","Dim"];

/* Postures : angles absolus en degrés. Tronc et tête mesurés depuis la verticale vers le haut,
   membres depuis la verticale vers le bas ; positif = vers l'avant (+x). Le personnage regarde à droite. */
const ST  = o=>({x:50,y:38,tr:0,hp:0,kn:0,sh:0,el:0,g:74,...o});
const SUP = o=>({x:54,y:69,tr:-90,hp:90,kn:90,ft:180,sh:100,el:100,...o});
