const PRO = o=>({x:46,y:69,tr:90,hp:-90,kn:-90,ft:0,sh:-95,el:-95,...o});
const QUAD= o=>({x:38,y:54,tr:75,hp:0,kn:-90,ft:-90,sh:0,el:0,hp2:0,kn2:-90,ft2:-90,sh2:0,el2:0,hw:90,hw2:90,g:74,c:["K","W","K2","W2"],...o});
const SIT = o=>({x:42,y:56,tr:0,hp:90,kn:0,ft:90,hp2:90,kn2:0,ft2:90,sh:0,el:0,g:74,c:["A2","T2"],...o});
const LS  = o=>({x:40,y:69,tr:-8,hp:90,kn:90,ft:150,sh:60,el:80,...o});
