const EX = Object.fromEntries(EXERCISES.map(e=>[e.id,e]));

/* Groupes musculaires utilisés par les filtres, déduits de la liste « Muscles ciblés » (m) de chaque exercice */
const MUSCLES = [
  ["Quadriceps",            e=>/quadriceps|droit fémoral/.test(e.m)],
  ["Ischio-jambiers",       e=>/ischio/.test(e.m)],
  ["Fessiers",              e=>/fessier/.test(e.m)],
  ["Hanches",                e=>/psoas|fléchisseurs de hanche/.test(e.m)],
  ["Hanches",                e=>/piriforme/.test(e.m)||(e.r==="Hanche"&&/rotateurs externes/.test(e.m))],
  ["Mollets",               e=>/triceps sural|gastrocn|soléaire|mollet/.test(e.m)],
  ["Chevilles",              e=>/tibial|péronier|cheville/.test(e.m)],
  ["Abdos",                  e=>/abdomen|obliques|transverse|gainage|tronc/.test(e.m)],
  ["Bas du dos",            e=>/érecteurs|multifides|lombes|lombaire|lombo/.test(e.m)],
  ["Haut du dos",           e=>/rhomboïdes|trapèze|grand dorsal|dentelé|grand rond|colonne thoracique/.test(e.m)],
  ["Pectoraux",             e=>/pectoral/.test(e.m)],
  ["Épaules",                e=>/deltoïde/.test(e.m)],
  ["Épaules",                e=>/coiffe|infra-épineux|sous-scapulaire|petit rond/.test(e.m)||(e.r==="Épaule"&&/rotateurs externes|mobilité de l'épaule/.test(e.m))],
  ["Biceps",                e=>/biceps|brachial/.test(e.m)],
  ["Triceps",               e=>/triceps(?! sural)/.test(e.m)],
  ["Avant-bras",             e=>/poignet|doigts|main|préhension/.test(e.m)],
  ["Cou",                   e=>/cervic|long du cou|long de la tête/.test(e.m)],
  ["Équilibre",             e=>e.r==="Équilibre"||/proprioception|équilibre|contrôle postural/.test(e.m)],
  ["Douleur",                e=>e.r==="Douleur"],
  ["Mobilité",               e=>/mobilité/.test(e.m)||/^Étirement/.test(e.n)]
];
/* Plusieurs règles peuvent mener au même nom simple (ex. deltoïdes et coiffe → Épaules) */
const MUSCLE_NAMES = [...new Set(MUSCLES.map(m=>m[0]))];
EXERCISES.forEach(e=>{ const lm={...e,m:e.m.toLowerCase()}; e.mg=[...new Set(MUSCLES.filter(([,t])=>t(lm)).map(m=>m[0]))]; });
